using System.Text.Json;
using Lecturer.Core.Entities;
using Lecturer.Infrastructure;
using Microsoft.EntityFrameworkCore;
namespace Lecturer.Api.Services;
public static class DemoData
{
    public static async Task Seed(AppDbContext db)
    {
        await LocalizedDemoData.Seed(db);
        var id = Guid.Parse("00000000-0000-0000-0000-000000000001");
        if (await db.Lectures.AnyAsync(l => l.Id == id)) return;
        var slides = new[] {
            new SlideDraft("Учиться — значит вспоминать", new[] { "Понимание — только начало", "Воспоминание укрепляет знания", "Ошибка помогает найти пробел" }, "Когда мы перечитываем конспект, текст кажется знакомым. Но знакомство не всегда означает, что мы сможем объяснить идею самостоятельно. Попробуйте закрыть материал и рассказать главное своими словами. Такое активное воспроизведение помогает увидеть, что вы уже понимаете, а к чему нужно вернуться. Сегодня мы разберём три простых инструмента: воспроизведение по памяти, повторение с интервалами и объяснение через примеры. Их можно применять к языкам, программированию и подготовке к экзаменам."),
            new SlideDraft("Активное воспроизведение", new[] { "Закройте учебный материал", "Ответьте на вопрос по памяти", "Сравните ответ с источником" }, "Представьте, что вы изучаете фотосинтез. Вместо очередного перечитывания задайте себе вопрос: что растение получает на входе и что производит на выходе? Ответьте без подсказки, затем проверьте ответ по учебнику. Пропущенная деталь — это полезный сигнал для следующего повторения. Важна обратная связь: если не проверить себя, можно закрепить ошибку. Начните с одного или двух вопросов после каждого небольшого раздела. Формулируйте ответы своими словами и отмечайте то, что пока не получается вспомнить."),
            new SlideDraft("Повторение с интервалами", new[] { "Возвращайтесь к теме несколько раз", "Увеличивайте интервалы постепенно", "Сложные вопросы повторяйте чаще" }, "Несколько коротких возвращений к теме в разные дни обычно полезнее, чем одно длинное занятие перед экзаменом. Например, повторите материал завтра, через несколько дней и ещё через неделю. Это лишь начальный план, а не универсальная формула. Если ответ легко вспоминается, интервал можно увеличить. Если тема вызывает трудности, вернитесь к ней раньше. Лучше сочетать интервалы с активным воспроизведением: сначала попробовать вспомнить, и только потом открыть конспект. Так повторение становится проверкой знания, а не просто знакомством с текстом."),
            new SlideDraft("Объяснение своими словами", new[] { "Назовите основную идею", "Приведите понятный пример", "Проверьте границы аналогии" }, "Выберите изученную идею и объясните её воображаемому собеседнику, который впервые слышит об этой теме. Используйте короткие фразы и конкретные примеры. Например, переменную в программе можно сравнить с подписанной коробкой. Но у любой аналогии есть границы: переменная — не физическая коробка, и правила её использования зависят от языка программирования. Если объяснение застревает на сложном термине, это повод уточнить его смысл. После объяснения вернитесь к надёжному источнику и проверьте, что упрощение не исказило идею."),
            new SlideDraft("Ваш следующий учебный шаг", new[] { "Выберите один небольшой раздел", "Составьте три вопроса", "Запланируйте следующее повторение" }, "Теперь соберём всё в простой план. Изучите один небольшой раздел. Закройте материал и запишите три вопроса по нему. Ответьте по памяти, затем проверьте себя и исправьте ошибки. Объясните самую сложную идею через пример. В конце назначьте время следующего повторения. Не нужно сразу менять все привычки: попробуйте этот подход на одной теме и посмотрите, что помогает именно вам. После лекции вы найдёте краткий конспект, тестовые вопросы и два небольших задания. Они помогут сразу применить изученные приёмы.")
        };
        var exercises = new
        {
            quiz = new[] {
            new QuizItem("Что лучше проверяет понимание материала?", new[] { "Перечитать знакомый текст", "Объяснить идею по памяти и проверить себя", "Выделить весь абзац", "Посмотреть на заголовок" }, 1, "Воспроизведение без подсказки обнаруживает пробелы, а проверка помогает исправить ошибки."),
            new QuizItem("Как выбрать интервал повторения?", new[] { "Всегда ровно месяц", "Повторять только накануне экзамена", "Учитывать, насколько легко вспоминается ответ", "Повторять только лёгкие темы" }, 2, "Интервал подстраивают под сложность: трудные вопросы повторяют раньше."),
            new QuizItem("Что нужно сделать после объяснения через аналогию?", new[] { "Проверить точность и границы аналогии", "Заменить аналогией все определения", "Не открывать источник", "Запомнить только пример" }, 0, "Аналогия упрощает идею, но может искажать отдельные детали. Сравните объяснение с источником.") },
            tasks = new[] { new TaskItem("Выберите знакомую тему и составьте три вопроса для активного воспроизведения.", "Пример для темы «Переменные»: что такое переменная? Как присвоить ей значение? Чем число отличается от строки? Ответьте, затем проверьте по учебнику."), new TaskItem("Составьте план трёх повторений и укажите, когда вы измените интервалы.", "Возможный план: завтра, через три дня, через неделю. Если воспроизведение затруднено — сократить следующий интервал; если ответ уверенный — постепенно увеличить.") }
        };
        db.Lectures.Add(new Lecture
        {
            Id = id,
            Title = "Как учиться и запоминать надолго",
            Description = "Три приёма, которые помогут превратить новую информацию в уверенные знания.",
            Subject = "Навыки обучения",
            Level = "Начальный",
            IsDemo = true,
            IsPublished = true,
            SourceName = "Демонстрационная лекция",
            Introduction = "Привет! Я ваш AI-лектор. Сегодня поговорим о том, как учиться осмысленно и запоминать надолго. Разберём активное воспроизведение, интервальные повторения и объяснение своими словами. Вы можете остановить лекцию в любой момент. Давайте начнём!",
            Summary = "Активное воспроизведение\nЗакройте материал и ответьте на вопросы по памяти. Затем сравните ответ с источником и исправьте неточности. Простое узнавание текста не гарантирует понимания.\n\nПовторение с интервалами\nВозвращайтесь к теме в разные дни. Постепенно увеличивайте интервалы, если ответ легко вспоминается. Сложные темы повторяйте раньше.\n\nОбъяснение своими словами\nСформулируйте основную идею и приведите конкретный пример. Проверяйте точность аналогии по источнику.\n\nПрактический план\nИзучите небольшой раздел → задайте три вопроса → ответьте по памяти → проверьте себя → назначьте следующее повторение.",
            ExercisesJson = JsonSerializer.Serialize(exercises, new JsonSerializerOptions(JsonSerializerDefaults.Web)),
            Slides = slides.Select((s, i) => new Slide { Id = Guid.NewGuid(), OrderIndex = i, NarrationText = s.Narration, ContentJson = JsonSerializer.Serialize(new { title = s.Title, bullets = s.Bullets }) }).ToList()
        });
        await db.SaveChangesAsync();
    }
}
